const BASE_PATH = "/functions/v1/everything-hub-site";
const ROOT = "https://vdceayvfgkwpgwixrhwi.supabase.co/functions/v1/everything-hub-site";
const esc = (s: string) => s.replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c] || c));
function shell(title: string, description: string, canonical: string, body: string) {
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+esc(description)+'"><title>'+esc(title)+'</title><link rel="canonical" href="'+esc(canonical)+'"><meta name="theme-color" content="#071b12"><style>body{margin:0;background:#06150e;color:#edf9ef;font:16px/1.6 system-ui,sans-serif}main{max-width:1040px;margin:auto;padding:28px 20px 60px}.brand{color:#baff70;font-weight:900}h1{font-size:clamp(30px,5vw,48px);line-height:1.12;margin:16px 0}h2{color:#d4f5a2;margin-top:30px}.intro{font-size:18px;color:#c3d9c9;max-width:760px}.panel{background:#0b2619;border:1px solid #235b3c;border-radius:16px;padding:18px;margin:18px 0}.links{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.links a{display:block;background:#0c2d1d;border:1px solid #286343;border-radius:12px;padding:12px;color:#d9f5c0;text-decoration:none}.links a:hover{border-color:#baff70}.muted,.crumb{color:#9db9a5;font-size:13px}.crumb a,a{color:#baff70}.cta{display:inline-block;background:#b5e77c;color:#102616;padding:11px 18px;border-radius:99px;text-decoration:none;font-weight:800;margin:8px 8px 8px 0}footer{border-top:1px solid #24553a;margin-top:36px;padding-top:16px;color:#9db9a5;font-size:13px}</style></head><body><main><div class="brand">EVERYTHING HUB — Everything within reach</div>'+body+'<footer>Compare sources and follow the original publisher for current details. <a href="'+ROOT+'/">Return to Everything Hub</a></footer></main></body></html>';
}
function indexPage() {
  const body = '<p class="crumb"><a href="'+ROOT+'/">Home</a> / Topics</p><h1>Explore 126 topics</h1><p class="intro">Browse 126 topic areas across eight discovery experiences: web, news, images, videos, shopping, places, business and research.</p><div class="links">'+TOPICS.map(t=>'<a href="'+ROOT+'/topics/'+t[0]+'/">'+esc(t[1])+' <span class="muted">— 8 discovery views</span></a>').join("")+'</div>';
  return shell("Explore 126 Topics | Everything Hub","Browse 126 topics across eight search categories.",ROOT+"/topics/",body);
}
function topicPage(topicSlug: string, categorySlug: string) {
  const topic = TOPICS.find(t=>t[0]===topicSlug), category = CATEGORIES.find(c=>c[0]===categorySlug);
  if (!topic || !category) return null;
  const slug=topic[0], name=topic[1], cat=category[0], catName=category[1], focus=category[2];
  const canonical=ROOT+"/topics/"+slug+"/"+cat+"/";
  const body='<p class="crumb"><a href="'+ROOT+'/">Home</a> / <a href="'+ROOT+'/topics/">Topics</a> / <a href="'+ROOT+'/topics/'+slug+'/">'+esc(name)+'</a> / '+esc(catName)+'</p><h1>'+esc(name)+': '+esc(catName)+'</h1><p class="intro">Explore '+esc(name)+' through '+esc(catName.toLowerCase())+'. This view focuses on '+esc(focus)+', helping you find useful starting points, compare sources and continue into deeper discovery.</p><section class="panel"><h2>What to explore</h2><p>Use this '+esc(catName.toLowerCase())+' view to investigate key questions about '+esc(name)+', identify relevant sources and follow material back to its original publisher. Check publication dates, compare independent sources and verify important claims before acting on them.</p><p class="muted">Topic: '+esc(name)+' · Experience: '+esc(catName)+' · Part of 126 topics and 8 discovery categories.</p><a class="cta" href="'+ROOT+'/?q='+encodeURIComponent(name)+'&mode='+cat+'">Search '+esc(name)+'</a><a class="cta" href="'+ROOT+'/topics/'+slug+'/">All 8 views for this topic</a></section><h2>Explore '+esc(name)+' in every category</h2><div class="links">'+CATEGORIES.map(c=>'<a href="'+ROOT+'/topics/'+slug+'/'+c[0]+'/">'+esc(c[1])+' <span class="muted">— '+esc(c[2])+'</span></a>').join("")+'</div><h2>Related topics</h2><div class="links">'+TOPICS.filter(t=>t[0]!==slug).slice(0,12).map(t=>'<a href="'+ROOT+'/topics/'+t[0]+'/'+cat+'/">'+esc(t[1])+' in '+esc(catName)+'</a>').join("")+'</div>';
  return shell(name+" "+catName+" | Everything Hub",name+" "+catName+" discovery: "+focus+". Explore sources with Everything Hub.",canonical,body);
}
function topicLanding(topicSlug: string) {
  const topic=TOPICS.find(t=>t[0]===topicSlug);
  if(!topic) return null;
  const slug=topic[0],name=topic[1];
  const body='<p class="crumb"><a href="'+ROOT+'/">Home</a> / <a href="'+ROOT+'/topics/">Topics</a> / '+esc(name)+'</p><h1>'+esc(name)+'</h1><p class="intro">Explore '+esc(name)+' across eight ways to discover information. Choose the experience that best fits what you need.</p><div class="links">'+CATEGORIES.map(c=>'<a href="'+ROOT+'/topics/'+slug+'/'+c[0]+'/"><strong>'+esc(c[1])+'</strong><br><span class="muted">'+esc(c[2])+'</span></a>').join("")+'</div>';
  return shell(name+" Discovery | Everything Hub","Explore "+name+" across eight discovery categories.",ROOT+"/topics/"+slug+"/",body);
}
function makeSitemap() {
  const urls=[ROOT+"/",ROOT+"/topics/"];
  for(const t of TOPICS){urls.push(ROOT+"/topics/"+t[0]+"/");for(const c of CATEGORIES)urls.push(ROOT+"/topics/"+t[0]+"/"+c[0]+"/");}
  return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls.map(u=>'<url><loc>'+u+'</loc></url>').join("")+'</urlset>';
}

function discoverIndexPage() {
  const links = CATEGORIES.map(([slug, label, description]) =>
    '<a href="' + ROOT + '/discover/' + encodeURIComponent(slug) + '/"><strong>' + esc(label) + '</strong><br><span>' + esc(description) + '</span></a>'
  ).join("");
  const body = '<main><p class="brand">EVERYTHING HUB</p><p class="crumb"><a href="' + ROOT + '/">Home</a> / Explore Pages</p><h1>Explore Pages</h1><p class="intro">Browse the eight search categories and discover public pages, subjects and source collections.</p><div class="links">' + links + '</div><a class="cta" href="' + ROOT + '/">Return to Everything Hub search</a></main>';
  return shell("Explore Pages — Everything Hub", "Explore public pages and source categories across Everything Hub.", ROOT + "/discover/", body);
}
function discoverCategoryPage(slug: string) {
  const category = CATEGORIES.find(([key]) => key === slug);
  if (!category) return null;
  const body = '<main><p class="brand">EVERYTHING HUB</p><p class="crumb"><a href="' + ROOT + '/">Home</a> / <a href="' + ROOT + '/discover/">Explore Pages</a> / ' + esc(category[1]) + '</p><h1>' + esc(category[1]) + ' pages</h1><p class="intro">' + esc(category[2]) + '</p><a class="cta" href="' + ROOT + '/?mode=' + encodeURIComponent(slug) + '">Search ' + esc(category[1]) + '</a><div class="links">' + CATEGORIES.map(([key, label, description]) => '<a href="' + ROOT + '/discover/' + encodeURIComponent(key) + '/"><strong>' + esc(label) + '</strong><br><span>' + esc(description) + '</span></a>').join("") + '</div></main>';
  return shell(category[1] + " Pages — Everything Hub", "Explore " + category[1] + " public pages and sources.", ROOT + "/discover/" + encodeURIComponent(slug) + "/", body);
}
function catalogIndexPage() {
  const links = CATEGORIES.map(([slug, label, description]) =>
    '<a href="' + ROOT + '/?mode=' + encodeURIComponent(slug) + '"><strong>' + esc(label) + ' catalogs</strong><br><span>Search public sources and supported catalog records</span></a>'
  ).join("");
  const body = '<main><p class="brand">EVERYTHING HUB</p><p class="crumb"><a href="' + ROOT + '/">Home</a> / Catalog Network</p><h1>Catalog Network</h1><p class="intro">Explore catalog records only where public source evidence supports them. Search results retain source links and provenance; candidate definitions are not presented as published records.</p><div class="links">' + links + '</div><a class="cta" href="' + ROOT + '/">Search Everything Hub</a></main>';
  return shell("Catalog Network — Everything Hub", "Explore the public-source catalog network and its supported record categories.", ROOT + "/catalogs/", body);
}

Deno.serve((req: Request) => {
  if(req.method!=="GET" && req.method!=="HEAD") return new Response("Method not allowed",{status:405,headers:{"Allow":"GET, HEAD"}});
  const url=new URL(req.url);
  let path=url.pathname;
  while(path.length>1 && path.endsWith("/")) path=path.slice(0,-1);
  let body=html, type="text/html; charset=utf-8", status=200;
  if(path.endsWith("/sitemap.xml")){body=makeSitemap();type="application/xml; charset=utf-8";}
  else if(path.endsWith("/robots.txt")){body="User-agent: *\nAllow: /\nSitemap: "+ROOT+"/sitemap.xml\n";type="text/plain; charset=utf-8";}
  else {
    const parts=path.split("/").filter(Boolean);
    const di=parts.indexOf("discover");
    const ci=parts.indexOf("catalogs");
    const ti=parts.indexOf("topics");
    if(di>=0) {
      const rendered=parts[di+1]?discoverCategoryPage(parts[di+1]):discoverIndexPage();
      if(rendered) body=rendered; else {body="Not found";type="text/plain; charset=utf-8";status=404;}
    }
    else if(ci>=0) body=catalogIndexPage();
    else if(ti>=0 && !parts[ti+1]) body=indexPage();
    else if(ti>=0 && parts[ti+1]) {
      const rendered=parts[ti+2]?topicPage(parts[ti+1],parts[ti+2]):topicLanding(parts[ti+1]);
      if(rendered) body=rendered; else {body="Not found";type="text/plain; charset=utf-8";status=404;}
    }
  }
  const rootPathRaw = new URL(ROOT).pathname;
  const rootPath = rootPathRaw.endsWith("/") ? rootPathRaw.slice(0, -1) : rootPathRaw;
  if(path === rootPath || path === rootPath + "/index.html" || path === "/") { body=html; type="text/html; charset=utf-8"; status=200; }
  const responseHeaders = new Headers();
  responseHeaders.set("content-type", type);
  responseHeaders.set("cache-control", "no-store");
  responseHeaders.set("x-content-type-options", "nosniff");
  responseHeaders.set("x-eh-release", "edge-homepage-v3-supabase-r3");
  const responseBody = req.method==="HEAD" ? null : new TextEncoder().encode(body);
  return new Response(responseBody,{status,headers:responseHeaders});
});
